  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: error.name, message: error.message };
    if ('cause' in error) result.cause = error.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (error as any)[prop]; });
    const processor = superJson.errorClassRegistry.getProcessor(error.name);
    return processor ? processor(result) : result;
  }
  const seen = new Set<Error>();
  function serialize(current: Error, depth: number): any {
    seen.add(current);
    const matches = !options!.classFilter.length || options!.classFilter.includes(current.name);
    const result: any = { name: current.name, message: matches && options!.sanitizeMessage ? sanitizeMessage(current.message) : current.message };
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (current as any)[prop];
    });
    if (matches && typeof current.stack === 'string') {
      if (options!.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(current.stack, options!);
      if (options!.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(current.stack, options!);
    }
    if (typeof AggregateError !== 'undefined' && current instanceof AggregateError) result.errors = current.errors;
    const cause = current.cause;
    if (cause instanceof Error && !seen.has(cause) && ((options!.includeCauses === 'direct' && depth === 0) || (options!.includeCauses === 'deep' && depth < options!.maxCauseDepth))) {
