      const serializedCause = serialize(cause, depth + 1);
      const restoredCause = new Error(serializedCause.message);
      Object.assign(restoredCause, serializedCause);
      result.cause = restoredCause;
    }
    const processor = superJson.errorClassRegistry.getProcessor(current.name);
    return processor ? processor(result) : result;
  }
  return serialize(error, 0);
}

